const [fs1, fs2, fs3, eng, sites] = await Promise.all([
  gm.grep({ pattern: 'featureset|feature-set|feature set', root: '/workspace/cleetus', scope: 'all', limit: 20 }),
  gm.grep({ pattern: 'FINAL scan|stream #|Stream #|streams #', root: '/workspace/cleetus', scope: 'all', limit: 20 }),
  gm.run_shell({ command: 'ls -la /workspace/cleetus/docs /workspace/cleetus/gaps /workspace/cleetus/runs 2>&1 | head -40' }),
  gm.run_shell({ command: 'grep -n "not a git" /workspace/cleetus/.jayzee/reference/engine-deep/README.md; echo "exit=$?"' }),
  gm.run_shell({ command: 'cd /workspace/cleetus && git status --short | head -5; git log --oneline -1; echo "site-tracked=$(git ls-files site | wc -l)"; grep -n "^site/" .gitignore' }),
]);
return { fs1: fs1.output ?? fs1, fs2: fs2.output ?? fs2, dirs: fs3.output, engine: eng.output, site: sites.output };
